-- GENERATED by gen_mxh3_vault.py -- models are generated, never hand-edited.
--   SAT_CASE_WORKFLOW_TASK
--   anchor      : HUB_CASE
--   grain       : Multi-Active SCD2 (data_7.js sats[].hist)
--   child key   : Task Code
--   feeders     : 1 -- one per (view, DECLARED ANCHOR EXPRESSION)
--   payload     : 8 attribute(s), NULL-PADDED TO THE SATELLITE
--
--   The child key is the MODEL'S declared key, read from data_7.js
--   sats[].childkey keyed by sats[].code. target.key_name is the HUB key
--   name and is null on all 1,888 satellite rows, so it is never read here.
--
--   The hashdiff is GUARDED against an all-null input: without the guard
--   every all-null row hashes to ONE value and the population collapses.

with feeders as (select * from (
    select
        md5(upper(HUB_CASE_BK__K0)) as HUB_CASE_HK,
        coalesce(nullif(trim(PROCESS_NAME),''),'') || '#' || coalesce(nullif(trim(FOLLOW_UP_DATE),''),'') as TASK_CODE,
        TASK_DESCRIPTION as TASK_NAME,
        PROCESS_NAME as TASK_TYPE,
        ASSIGNED_TO as ASSIGNED_TO_REFERENCE,
        FOLLOW_UP_DATE as DUE_DATE,
        COMPLETION_DATE as COMPLETED_DATE,
        TASK_STATUS as TASK_STATUS,
        ACTION as OUTCOME,
        QUEUE_NAME as QUEUE_REFERENCE,
        'MAXI_HLTH_CLM_VW_DATA_CLAIM_DETAIL_FOLLOWUP_ATTRIBUTES_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_clm_cd_followup_attr_pv') }}
    where HUB_CASE_K0__EMIT
)), hashed as (select *,
        case when TASK_NAME is not null or TASK_TYPE is not null or ASSIGNED_TO_REFERENCE is not null or DUE_DATE is not null or COMPLETED_DATE is not null or TASK_STATUS is not null or OUTCOME is not null or QUEUE_REFERENCE is not null
             then md5(upper(coalesce(TASK_NAME::varchar,'') || '||' || coalesce(TASK_TYPE::varchar,'') || '||' || coalesce(ASSIGNED_TO_REFERENCE::varchar,'') || '||' || coalesce(DUE_DATE::varchar,'') || '||' || coalesce(COMPLETED_DATE::varchar,'') || '||' || coalesce(TASK_STATUS::varchar,'') || '||' || coalesce(OUTCOME::varchar,'') || '||' || coalesce(QUEUE_REFERENCE::varchar,'')))
        end as SAT_CASE_WORKFLOW_TASK_HASHDIFF
    from feeders)

select * from hashed
where HUB_CASE_HK is not null
  and SAT_CASE_WORKFLOW_TASK_HASHDIFF is not null
  and TASK_CODE is not null
